-- ============================================================
-- 007_interim_pricing.sql
-- ============================================================
--
-- Replaces the 002 placeholder pricing (flat NGN 1,000 same-zone /
-- NGN 2,000 cross-zone over 14 zones) with the interim formula output:
-- 25 zones, 600 symmetric cross-zone prices, NGN 3,100 - 6,600.
--
--   price = round_to_100(3000 + 60 * haversine_km * 1.4)
--
-- Generated by interim_pricing_generator.py in this directory, which holds
-- the zone coordinates. Source data: interim_zone_pricing_final.json.
--
-- STILL A PLACEHOLDER. These are not client-confirmed rates. The client's
-- own sheet had 21 unpriced pairs and 58 directional mismatches over 15%
-- (see ../client_questions.txt), so it could not be loaded as-is. The
-- zone_pricing.source column records where each row came from, so real
-- prices stay distinguishable. Replacing them is a FULL-TABLE SWAP of
-- zone_pricing, not a patch.
--
-- Zones are upserted BY NAME, never recreated: jobs.pickup_zone_id and
-- dropoff_zone_id are FKs to zones(id), so recreating zones would break
-- historical jobs.
--
-- The 300 pairs below are listed once each and mirrored in SQL, making
-- symmetry an invariant of the migration rather than 600 hand-listed rows
-- that have to agree.
--
-- Idempotent: applied by hand to anx-dev and production, then again by the
-- GitHub integration on merge to main.

-- ── 1. Provenance column ──────────────────────────────────

ALTER TABLE zone_pricing ADD COLUMN IF NOT EXISTS source text;


-- ── 2. Guard ──────────────────────────────────────────────
-- Fail loudly if the database holds a zone this file does not price, rather
-- than silently leaving it unpriced after the swap below.

DO $$
DECLARE stray text;
BEGIN
  SELECT string_agg(name, ', ' ORDER BY name) INTO stray
  FROM zones WHERE name NOT IN ('Airport Road', 'Apo', 'Asokoro', 'Central Area', 'Dakwo', 'Durumi', 'Dutse', 'Galadimawa', 'Garki', 'Gudu', 'Gwarinpa', 'Jabi', 'Jahi', 'Kado', 'Karu', 'Kubwa', 'Kuje', 'Lokogoma', 'Lugbe', 'Maitama', 'Mpape', 'Nyanya', 'Utako', 'Wuse', 'Wuse 2');
  IF stray IS NOT NULL THEN
    RAISE EXCEPTION
      'Zone(s) absent from the interim pricing list would be left unpriced: %', stray;
  END IF;
END $$;


-- ── 3. Zones: add the missing ones, keep existing ids ────

INSERT INTO zones (name)
SELECT v.name
FROM (VALUES
  ('Airport Road'),
  ('Apo'),
  ('Asokoro'),
  ('Central Area'),
  ('Dakwo'),
  ('Durumi'),
  ('Dutse'),
  ('Galadimawa'),
  ('Garki'),
  ('Gudu'),
  ('Gwarinpa'),
