  ('Lugbe'),
  ('Maitama'),
  ('Mpape'),
  ('Nyanya'),
  ('Utako'),
  ('Wuse'),
  ('Wuse 2')
) AS v(name)
WHERE NOT EXISTS (SELECT 1 FROM zones z WHERE z.name = v.name);


