), directed AS (
  SELECT a AS from_name, b AS to_name, price FROM pair
  UNION ALL
  SELECT b, a, price FROM pair          -- mirror: pricing is symmetric
)
INSERT INTO zone_pricing (from_zone_id, to_zone_id, base_price, source)
SELECT zf.id, zt.id, d.price, 'interim-formula-2026-09'
FROM directed d
JOIN zones zf ON zf.name = d.from_name
JOIN zones zt ON zt.name = d.to_name;


-- ── 5. Same-zone base fee ────────────────────────────────
-- The generated data is cross-zone only, but the API looks up an exact
-- (from, to) pair, so a same-zone delivery would fail with "No pricing for
-- this zone combination" without these rows.
--
-- NGN 3,000 is what the formula yields at zero distance: the distance term
-- goes to zero, leaving BASE_FEE. So the value is method-consistent. It still
-- carries its own source marker because the source data has no same-zone
-- entries at all — these rows extrapolate the formula to a case the client
-- never priced, and that assumption needs confirming separately.

INSERT INTO zone_pricing (from_zone_id, to_zone_id, base_price, source)
SELECT z.id, z.id, 3000, 'interim-samezone-basefee-2026-09'
FROM zones z;


-- ── 6. Uniqueness ────────────────────────────────────────
-- The API reads pricing with .maybeSingle(), which errors on duplicates, so a
-- duplicate pair would break job creation outright. Postgres has no
-- ADD CONSTRAINT IF NOT EXISTS, hence the catalog check.

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    WHERE t.relname = 'zone_pricing' AND c.conname = 'zone_pricing_from_to_key'
  ) THEN
    ALTER TABLE zone_pricing
      ADD CONSTRAINT zone_pricing_from_to_key UNIQUE (from_zone_id, to_zone_id);
  END IF;
END $$;
